// Validates packs/*.yaml and writes src/generated/{types,packs}.ts.
//   node scripts/build.ts           write the generated files
//   node scripts/build.ts --check   fail when the committed files are stale or a pack is invalid
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";
import { parse } from "yaml";
import { PACK_SCHEMA } from "../src/schema.ts";
import { validatePack } from "../src/validate.ts";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const packsDir = join(root, "packs");
const outDir = join(root, "src/generated");
const BANNER = "// Generated by scripts/build.ts from packs/*.yaml and src/schema.ts. Do not edit.";

const files = readdirSync(packsDir)
  .filter((f) => f.endsWith(".yaml"))
  .sort();
const packs: { id: string }[] = [];
const problems: string[] = [];
for (const file of files) {
  const pack = parse(readFileSync(join(packsDir, file), "utf8")) as { id: string };
  const errors = validatePack(pack);
  for (const error of errors) problems.push(`${file}: ${error}`);
  if (pack.id !== file.replace(/\.yaml$/, ""))
    problems.push(`${file}: id must match the file name`);
  packs.push(pack);
}
if (problems.length > 0) {
  console.error(`Invalid knowledge packs:\n  ${problems.join("\n  ")}`);
  process.exit(1);
}

const types = await compile(PACK_SCHEMA as never, "KnowledgePack", {
  bannerComment: BANNER,
  additionalProperties: false,
  format: false,
});
const registry = [
  BANNER,
  'import type { KnowledgePack } from "./types.ts";',
  "",
  `export const PACKS: readonly KnowledgePack[] = ${JSON.stringify(packs, null, 2)};`,
  "",
].join("\n");
const next = { "types.ts": `${types}\n`, "packs.ts": registry };

if (process.argv.includes("--check")) {
  const stale = Object.entries(next).filter(([name, content]) => {
    try {
      return readFileSync(join(outDir, name), "utf8") !== content;
    } catch {
      return true;
    }
  });
  if (stale.length > 0) {
    console.error(
      `Generated packs are stale. Run "pnpm --filter @itza/knowledge build:packs" and commit:\n  ${stale.map(([n]) => `src/generated/${n}`).join("\n  ")}`,
    );
    process.exit(1);
  }
  console.log("Generated packs are up to date.");
} else {
  for (const [name, content] of Object.entries(next)) writeFileSync(join(outDir, name), content);
  console.log(`Wrote ${files.length} packs.`);
}
